package com.careerpilot.modules.interview.service;
import com.careerpilot.exception.*;import com.careerpilot.modules.auth.entity.User;import com.careerpilot.modules.careerai.dto.CareerAiDtos.*;import com.careerpilot.modules.careerai.service.CareerAiService;import com.careerpilot.modules.interview.dto.InterviewDtos.*;import com.careerpilot.modules.interview.entity.*;import com.careerpilot.modules.interview.repository.InterviewSessionRepository;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.time.Instant;import java.util.*;
@Service public class InterviewSessionService{public static final String DISCLAIMER="AI-generated coaching for interview practice only. Scores and feedback are not hiring, employability, psychological, or recruiter assessments.";private final InterviewSessionRepository repository;private final CareerAiService ai;private final ObjectMapper json;public InterviewSessionService(InterviewSessionRepository repository,CareerAiService ai,ObjectMapper json){this.repository=repository;this.ai=ai;this.json=json;}
 @Transactional public Session start(User user,StartRequest request){if(!List.of(3,5,10).contains(request.questionCount()))throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"Question count must be 3, 5, or 10");var result=ai.interview(user,new InterviewRequest(request.targetCareer(),aiMode(request.interviewType()),request.focusArea(),null,null));var session=new InterviewSession();session.setUser(user);session.setTargetCareer(request.targetCareer());session.setInterviewType(request.interviewType());session.setMode(request.mode());session.setFocusArea(request.focusArea());session.setQuestionCount(request.questionCount());session.setCurrentQuestion(result.question());session.setProvider(result.provider());session.setModel(result.model());repository.save(session);return map(session);}
 @Transactional public Session answer(User user,UUID id,SubmitAnswerRequest request){var session=owned(user,id);if(session.getStatus()!=InterviewStatus.IN_PROGRESS)throw new ApiException(HttpStatus.CONFLICT,"This interview is already complete");var result=ai.interview(user,new InterviewRequest(session.getTargetCareer(),aiMode(session.getInterviewType()),session.getFocusArea(),session.getCurrentQuestion(),request.transcript()));var feedback=result.feedback();var answer=new InterviewAnswer();answer.setSession(session);answer.setSequenceNumber(session.getCompletedAnswers()+1);answer.setQuestion(session.getCurrentQuestion());answer.setTranscript(request.transcript().trim());answer.setStrengths(write(feedback.strengths()));answer.setNeedsImprovement(write(feedback.needsImprovement()));answer.setNextFocus(feedback.nextFocus());answer.setSuggestedAnswer(feedback.suggestedAnswer());answer.setTopicsToReview(write(feedback.topicsToReview()));answer.setTechnicalCorrectness(feedback.scores().technicalCorrectness());answer.setRelevance(feedback.scores().relevance());answer.setAnswerStructure(feedback.scores().answerStructure());answer.setCompleteness(feedback.scores().completeness());answer.setCommunicationClarity(feedback.scores().communicationClarity());answer.setAnswerDurationSeconds(request.answerDurationSeconds());session.getAnswers().add(answer);session.setCompletedAnswers(session.getCompletedAnswers()+1);session.setCurrentQuestion(result.question());if(session.getCompletedAnswers()>=session.getQuestionCount()){session.setStatus(InterviewStatus.COMPLETED);session.setCompletedAt(Instant.now());session.setOverallCoachingScore(aggregate(session.getAnswers()));}repository.save(session);return map(session);}
 @Transactional(readOnly=true)public Session get(User user,UUID id){return map(owned(user,id));}@Transactional(readOnly=true)public List<History>history(User user){return repository.findByUserIdOrderByStartedAtDesc(user.getId()).stream().map(v->new History(v.getId(),v.getTargetCareer(),v.getInterviewType(),v.getMode(),v.getQuestionCount(),v.getCompletedAnswers(),v.getStatus(),v.getOverallCoachingScore(),v.getStartedAt(),v.getCompletedAt())).toList();}
 private InterviewSession owned(User user,UUID id){return repository.findByIdAndUserId(id,user.getId()).orElseThrow(()->new NotFoundException("Interview session not found"));}private String aiMode(String type){return switch(type){case"TECHNICAL"->"TECHNICAL";case"BEHAVIORAL"->"RESUME_BASED";default->"SKILL_GAP_FOCUSED";};}private int aggregate(List<InterviewAnswer>answers){return(int)Math.round(answers.stream().mapToInt(v->v.getTechnicalCorrectness()+v.getRelevance()+v.getAnswerStructure()+v.getCompleteness()+v.getCommunicationClarity()).average().orElse(0)/5.0);}private String write(List<String>v){try{return json.writeValueAsString(v);}catch(Exception e){return"[]";}}private List<String>read(String v){try{return json.readValue(v==null?"[]":v,new TypeReference<>(){});}catch(Exception e){return List.of();}}
 private Session map(InterviewSession v){return new Session(v.getId(),v.getTargetCareer(),v.getInterviewType(),v.getMode(),v.getFocusArea(),v.getQuestionCount(),v.getStatus(),v.getCurrentQuestion(),v.getCompletedAnswers(),v.getOverallCoachingScore(),v.getProvider(),v.getModel(),v.getStartedAt(),v.getCompletedAt(),v.getAnswers().stream().map(a->new Answer(a.getId(),a.getSequenceNumber(),a.getQuestion(),a.getTranscript(),read(a.getStrengths()),read(a.getNeedsImprovement()),a.getNextFocus(),a.getSuggestedAnswer(),read(a.getTopicsToReview()),new Scores(a.getTechnicalCorrectness(),a.getRelevance(),a.getAnswerStructure(),a.getCompleteness(),a.getCommunicationClarity()),a.getAnswerDurationSeconds(),a.getCreatedAt())).toList(),DISCLAIMER);}
}
